 // Legal and agenda UI. Inserted into the app controller by the build.
 let coLegalFilter='all';
 const coLabel=key=>K.statuses[key]||key;
 const coDriver=id=>ops.drivers.find(d=>d.id===id)?.name||'Sem motorista';
 const coState=c=>K.contractStatus(c);
 const coTone=status=>status==='signed'?'green':['draft','cancelled','refused','expired'].includes(status)?'':'amber';
 function coFormActions(label){return `<div class="form-actions"><button type="submit" class="btn primary">${label}</button></div>`;}
 function lawyer(){K.ensure(ops);const all=K.contracts(ops),list=all.filter(c=>coLegalFilter==='all'||(coLegalFilter==='pending'?['queued','awaiting','partial'].includes(coState(c)):coState(c)===coLegalFilter));return `<div class="co-module">`+heading('MEU ADVOGADO · DOCUMENTOS E ETAPAS','Cada vínculo, com a versão certa.','Prepare minutas, confira modelos e veja quem assinou e quem ainda falta. Todo registro desta demonstração é fictício.',btn('Criar minuta','co-new-contract','primary'))+`<div class="stats">${stat('Na fila de envio',String(all.filter(c=>c.status==='queued').length),'A revisão não envia documentos')}${stat('Assinaturas pendentes',String(all.filter(c=>['awaiting','partial'].includes(coState(c))).length),'Motorista e locadora acompanhados separadamente')}${stat('Locações assinadas',String(all.filter(c=>c.modelId==='rental'&&coState(c)==='signed').length),'Somente registros demonstrativos, com as duas partes')}${stat('Modelos disponíveis',String(K.models.length),'Versões e campos para conferência')}</div><div class="notice">Área de organização jurídica. Modelos são rascunhos para revisão por advogado; nenhum documento é enviado ou assinado de verdade. Não inserir CPF, CNH ou documentos pessoais.</div><div class="gap">${section('Contratos e termos','Do cadastro à assinatura. A fila não libera o carro.')}</div><div class="co-filters">${[['all','Todos'],['draft','Minutas'],['review','Em revisão'],['pending','Fila e assinatura'],['signed','Assinados'],['expired','Vencidos'],['refused','Recusados'],['cancelled','Cancelados']].map(([key,label])=>btn(label,'co-filter',coLegalFilter===key?'primary':'',`data-value="${key}" aria-pressed="${coLegalFilter===key}"`)).join('')}</div>${panel('Controle por vínculo',table(['Documento / versão','Motorista / carro','Vigência / aluguel','Etapa','Quem assinou','Abrir'],list.map(c=>`<tr><td><strong>${esc(c.id)} · ${esc(K.models.find(m=>m.id===c.modelId)?.name||c.modelId)}</strong><small>Documento v${c.version} · modelo v${c.modelVersion}</small></td><td>${esc(coDriver(c.driverId))}<small>${esc(c.vehicleId)}</small></td><td>${date(c.startDate)} a ${date(c.endDate)}<small>${cash(c.weekly)} / semana</small></td><td>${tag(coLabel(coState(c)),coTone(coState(c)))}</td><td><span>${c.signatures.driver?.recorded?'✓':'○'} Motorista</span><small>${c.signatures.company?.recorded?'✓':'○'} Locadora</small></td><td>${btn('Abrir documento','co-contract','',`data-id="${c.id}"`)}</td></tr>`).join('')||'<tr><td colspan="6">Nenhum documento nesta etapa. Crie uma minuta a partir de um modelo.</td></tr>'))}<div class="gap">${section('Biblioteca de modelos','Cinco documentos para organizar o vínculo. O texto de cada versão fica disponível para conferência.')}</div><div class="co-model-grid">${K.catalog(ops).map(m=>`<article class="co-model"><span class="eyebrow">MODELO V${m.version}</span><h3>${esc(m.name)}</h3><p>${esc(m.description)}</p><div class="actions">${btn('Ver modelo','co-model','',`data-model="${m.id}"`)}${btn('Usar modelo','co-new-contract','',`data-model="${m.id}"`)}</div></article>`).join('')}</div></div>`;}
 function coContractForm(c=null,modelId='rental'){K.ensure(ops);const d=ops.drivers.find(d=>d.stage==='ready')||ops.drivers[0];return `<form id="co-contract-form">${c?`<input type="hidden" name="entityId" value="${c.id}">`:''}<div class="notice">${c?'Salvar cria uma nova versão e reinicia a revisão e os registros de assinatura. A versão anterior fica no histórico.':'Minuta demonstrativa. Revise condições com advogado antes de qualquer uso real.'}</div><div class="fields gap">${c?`<label class="field">Modelo<input disabled value="${esc(K.models.find(m=>m.id===c.modelId)?.name)}"></label>`:select('modelId','Modelo',modelId,K.models.map(m=>[m.id,m.name]))}${select('driverId','Motorista',c?.driverId||d.id,ops.drivers.map(d=>[d.id,d.name]))}${select('vehicleId','Veículo',c?.vehicleId||d.nextVehicleId||d.vehicleId||'RV-001',M.vehicles(ops).map(v=>[v.id,v.id+' · '+v.model]))}${input('startDate','Início da vigência',c?.startDate||K.operatingDate,'type="date" required')}${input('endDate','Fim da vigência',c?.endDate||'2028-01-24','type="date" required')}${input('weekly','Aluguel semanal · R$',c?.weekly||ops.book.contract.weekly,'type="number" min="0.01" step="0.01" required')}${input('deposit','Caução exigida · R$',c?.deposit??ops.program?.policy?.depositAmount??1500,'type="number" min="0" step="0.01" required')}${input('kmLimit','Limite de km por semana',c?.kmLimit??1500,'type="number" min="0" step="1" required')}</div><label class="field gap">Condições e pontos para revisão<textarea name="conditions" maxlength="1500" rows="5" required placeholder="Condições comerciais e pontos a validar; sem documentos ou dados pessoais.">${esc(c?.conditions||'Condições demonstrativas pendentes de aprovação comercial e jurídica.')}</textarea></label>${coFormActions(c?'Salvar nova versão da minuta':'Criar minuta demonstrativa')}</form>`;}
 function coContractBody(id){const c=K.contracts(ops).find(c=>c.id===id);if(!c)throw new RangeError('Contrato não encontrado.');const p=K.preview(ops,c),status=coState(c),openState=!['cancelled','refused','expired'].includes(status);return `<div class="co-module"><div class="notice">REGISTRO DEMONSTRATIVO. As marcações abaixo não produzem assinatura eletrônica, envio nem validade jurídica.</div><div class="co-document-header gap"><div><h3>${esc(p.model.name)} · ${esc(c.id)}</h3><p class="caption">${esc(coDriver(c.driverId))} · ${esc(c.vehicleId)} · documento v${c.version} / modelo v${c.modelVersion}</p></div>${tag(coLabel(status),coTone(status))}</div><div class="co-contract-summary">${row('Vigência',date(c.startDate)+' a '+date(c.endDate))}${row('Locação / caução',cash(c.weekly)+' / '+cash(c.deposit))}${row('Revisão da versão',c.reviewedVersion===c.version?'Conferências registradas':'Pendente',K.reviewItems.filter(([key])=>!c.review?.[key]).map(([,name])=>name).join(' · '))}</div>${p.missing.length?`<div class="notice amber gap">Campos em aberto: ${p.missing.map(esc).join(', ')}. Corrija a minuta antes de revisar.</div>`:''}<div class="co-signatures gap">${[['driver','Motorista'],['company','Locadora']].map(([party,title])=>`<div class="co-signature"><strong>${title}</strong><span>${c.signatures[party]?.recorded?'✓ Registro demonstrativo concluído':'○ Ainda não registrado'}</span><small>${c.signatures[party]?.recorded?date(c.signatures[party].at):'Pendente de conferência da parte'}</small>${['awaiting','partial'].includes(c.status)&&!c.signatures[party]?.recorded?btn('Simular registro da '+(party==='driver'?'parte motorista':'locadora'),'co-sign','',`data-id="${c.id}" data-party="${party}"`):''}</div>`).join('')}</div><div class="actions gap">${openState?btn('Editar / gerar nova versão','co-edit-contract','',`data-id="${c.id}"`):''}${['draft','review'].includes(c.status)?btn('Revisar esta versão','co-review','primary',`data-id="${c.id}"`):''}${c.status==='review'?btn('Colocar na fila','co-queue','primary',`data-id="${c.id}"`):''}${c.status==='queued'?btn('Simular envio para assinatura','co-await','primary',`data-id="${c.id}"`):''}${['queued','awaiting','partial'].includes(c.status)?btn('Registrar recusa','co-refuse','',`data-id="${c.id}"`):''}${!['cancelled','refused'].includes(c.status)?btn('Cancelar com motivo','co-cancel','',`data-id="${c.id}"`):''}</div>${c.reason?`<p class="notice amber gap">Motivo: ${esc(c.reason)}</p>`:''}<details class="gap" open><summary>Prévia integral da minuta · v${c.version}</summary><pre class="co-document">${esc(p.body)}</pre></details><details><summary>Versões e histórico (${c.history.length})</summary>${c.history.slice().reverse().map(h=>`<article class="co-version"><strong>Documento v${h.version} · ${esc(h.action)}</strong><p class="caption">${esc(String(h.at).slice(0,10))}${h.status?' · '+coLabel(h.status):''}</p>${h.conditions!==undefined?`<p>${date(h.startDate)} a ${date(h.endDate)} · ${cash(h.weekly)} / semana</p><p>${esc(h.conditions)}</p><p class="caption">Registros desta versão: motorista ${h.signatures?.driver?.recorded?'conferido':'pendente'} · locadora ${h.signatures?.company?.recorded?'conferida':'pendente'}.</p><details><summary>Texto da versão preservada</summary><pre class="co-document">${esc(K.preview(ops,{...c,...h}).body)}</pre></details>`:''}</article>`).join('')}</details><p class="caption">Registro jurídico não movimenta caixa, não quita cobranças e não entrega o carro. A liberação depende do conjunto de conferências no kanban.</p></div>`;}
 function coReviewForm(id){const c=K.contracts(ops).find(c=>c.id===id);return `<form id="co-review-form"><input type="hidden" name="entityId" value="${c.id}"><p>Conferência manual do documento ${esc(c.id)} · versão ${c.version}. O sistema não realizou análise jurídica.</p>${K.reviewItems.map(([key,label])=>`<label class="check"><input name="${key}" type="checkbox" required ${c.review?.[key]?'checked':''}>${label}</label>`).join('')}${coFormActions('Registrar revisão manual desta versão')}</form>`;}
 function coIso(d){return d.toISOString().slice(0,10);}
 function coDay(value){return new Date(value+'T12:00:00Z');}
 function coDateRange(anchor,view){const d=coDay(anchor);if(view==='month'){const first=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),1,12)),last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0,12));return [coIso(first),coIso(last)];}const day=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-day);const end=new Date(d);end.setUTCDate(end.getUTCDate()+6);return [coIso(d),coIso(end)];}
 function agenda(){K.ensure(ops);const view=ops.agenda.view||'week',anchor=ops.agenda.anchor||K.operatingDate,[start,end]=coDateRange(anchor,view),all=K.agendaItems(ops),list=all.filter(e=>e.date>=start&&e.date<=end),pending=all.filter(e=>e.status==='open'),today=pending.filter(e=>e.date===anchor),late=pending.filter(e=>e.date<anchor),title=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'}).format(coDay(anchor));return `<div class="co-module">`+heading('AGENDA E COMPROMISSOS','Nada importante fica solto.','Cobranças, etapas, contratos e cuidados aparecem junto dos seus compromissos. Jan/2027 é o calendário do exemplo.',btn('Fuso: '+(ops.agenda.timeZone||'America/Sao_Paulo'),'co-timezone')+btn('Novo compromisso','co-new-appointment','primary'))+`<div class="stats">${stat('Na data de referência',String(today.length),date(anchor)+' · pendências abertas')}${stat('Antes da referência',String(late.length),'Conferir pendências anteriores na origem')}${stat('Compromissos manuais',String(ops.agenda.events.filter(e=>e.status==='open').length),'Com responsável, vínculo e lembrete')}${stat('Pendências automáticas',String(pending.filter(e=>e.derived).length),'Mesmos registros do restante da operação')}</div><div class="co-agenda-controls"><div class="actions">${btn('← Anterior','co-agenda-shift','',`data-dir="-1"`)}<strong>${esc(title)}</strong>${btn('Próximo →','co-agenda-shift','',`data-dir="1"`)}${btn('Referência do exemplo','co-agenda-today')}</div><div class="actions">${[['week','Semana'],['month','Mês']].map(([key,label])=>btn(label,'co-agenda-view',view===key?'primary':'',`data-view="${key}" aria-pressed="${view===key}"`)).join('')}</div></div><div class="co-calendar ${view==='month'?'co-month':'co-week'}">${coCalendar(start,end,list,view)}</div><div class="gap">${panel('Agenda detalhada · '+date(start)+' a '+date(end),table(['Quando','Compromisso','Responsável / vínculo','Estado','Ação'],list.map(coAgendaRow).join('')||'<tr><td colspan="5">Nenhum compromisso neste período. Cadastre um ou navegue pelas datas.</td></tr>'))}</div>${late.length?`<details class="gap"><summary>Pendências anteriores à referência (${late.length})</summary>${table(['Quando','Compromisso','Responsável / vínculo','Estado','Ação'],late.map(coAgendaRow).join(''))}</details>`:''}<div class="notice gap">Lembretes são exibidos com o aplicativo aberto. Não há notificações por WhatsApp, e-mail ou celular nesta versão. Concluir uma pendência automática exige conferir o registro original; a agenda não confirma dinheiro nem assinatura.</div></div>`;}
 function coCalendar(start,end,items,view){const from=coDay(start),last=coDay(end),days=[];if(view==='month'){const offset=(from.getUTCDay()+6)%7;for(let i=0;i<offset;i++)days.push('<div class="co-day co-outside" aria-hidden="true"></div>');}while(from<=last){const iso=coIso(from),entries=items.filter(e=>e.date===iso),weekday=new Intl.DateTimeFormat('pt-BR',{weekday:'short',timeZone:'UTC'}).format(from);days.push(`<section class="co-day ${iso===K.operatingDate?'co-reference':''}"><h3><span>${esc(weekday)}</span><strong>${from.getUTCDate()}</strong></h3>${entries.slice(0,view==='month'?2:4).map(e=>`<button type="button" class="co-cal-event ${e.status==='done'?'co-done':''}" data-action="co-agenda-detail" data-id="${esc(e.id)}"><small>${esc(e.time)} · ${e.derived?'origem':'manual'}</small><span>${esc(e.title)}</span></button>`).join('')}${entries.length>(view==='month'?2:4)?`<span class="caption">+${entries.length-(view==='month'?2:4)} na lista abaixo</span>`:''}${!entries.length?'<span class="caption">Sem compromissos</span>':''}</section>`);from.setUTCDate(from.getUTCDate()+1);}return days.join('');}
 function coAgendaRow(e){return `<tr><td><strong>${date(e.date)}</strong><small>${esc(e.time)} · aviso ${e.reminder===1440?'1 dia antes':e.reminder?'com '+e.reminder+' min':'no horário'}</small></td><td>${esc(e.title)}<small>${e.derived?'Automático · registro de origem':'Compromisso manual'}</small></td><td>${esc(e.owner)}<small>${e.driverId?esc(coDriver(e.driverId)):''}${e.vehicleId?' · '+esc(e.vehicleId):''}</small></td><td>${tag(e.status==='done'?'Concluído':e.status==='cancelled'?'Cancelado':'Pendente',e.status==='done'?'green':e.status==='open'?'amber':'')}</td><td>${btn('Abrir','co-agenda-detail','',`data-id="${esc(e.id)}"`)}${e.derived?link('Conferir na origem →','go-'+K.originFor(e)):e.status==='open'?link('Concluir','co-agenda-complete',`data-id="${e.id}"`):''}</td></tr>`;}
 function coAppointmentForm(e=null){return `<form id="co-appointment-form">${e?`<input type="hidden" name="entityId" value="${e.id}">`:''}<div class="fields">${input('title','Compromisso',e?.title||'','required maxlength="100"')}${input('owner','Responsável',e?.owner||'Gestão RODAVOLT','required maxlength="100"')}${input('date','Data',e?.date||ops.agenda.anchor||K.operatingDate,'type="date" required')}${input('time','Horário',e?.time||'09:00','type="time" required')}${select('driverId','Motorista relacionado',e?.driverId||'',[['','Sem vínculo'],...ops.drivers.map(d=>[d.id,d.name])])}${select('vehicleId','Carro relacionado',e?.vehicleId||'',[['','Sem vínculo'],...M.vehicles(ops).map(v=>[v.id,v.id+' · '+v.model])])}${select('reminder','Lembrete no aplicativo',e?.reminder??60,[['0','No horário'],['15','15 minutos antes'],['30','30 minutos antes'],['60','1 hora antes'],['1440','1 dia antes']])}${e?select('status','Situação',e.status,[['open','Pendente'],['done','Concluído'],['cancelled','Cancelado']]):''}</div><label class="field gap">Observações<textarea name="note" maxlength="1000" rows="3">${esc(e?.note||'')}</textarea></label><p class="caption">Aviso dentro do aplicativo aberto. Não envia mensagens ou notificações externas.</p>${coFormActions(e?'Salvar compromisso':'Criar compromisso')}</form>`;}
 function coordinationAction(action,e){if(!action.startsWith('co-'))return false;K.ensure(ops);const id=e.dataset.id;
  if(action==='co-timezone'){open('Horários da operação',`<form id="co-timezone-form">${select('timeZone','Fuso dos compromissos',ops.agenda.timeZone,K.timeZones)}<p class="caption gap">O motorista e a gestão veem o horário deste fuso, mesmo com o dispositivo em outro local. Mudar não altera o dia e a hora que você cadastrou.</p>${coFormActions('Salvar fuso da operação')}</form>`);return true;}
  if(action==='co-filter'){coLegalFilter=e.dataset.value;render();return true;}
  if(action==='co-new-contract'){open('Nova minuta',coContractForm(null,e.dataset.model||'rental'));return true;}
  if(action==='co-model'){const m=K.catalog(ops).find(m=>m.id===e.dataset.model),versions=ops.legal.modelVersions.filter(v=>v.id===m.id).sort((a,b)=>b.version-a.version);open('Modelo · '+m.name,`<div class="notice">Modelo atual v${m.version} · demonstrativo e sujeito à revisão jurídica manual. Alterar o modelo não muda os documentos já criados.</div><pre class="co-document gap">${esc(m.body)}</pre><div class="actions">`+btn('Criar minuta com este modelo','co-new-contract','primary',`data-model="${m.id}"`)+btn('Editar modelo / nova versão','co-edit-model','',`data-model="${m.id}"`)+`</div><details class="gap"><summary>Todas as versões do modelo (${versions.length})</summary>${versions.map(v=>`<details><summary>Modelo v${v.version} · ${esc(String(v.createdAt||'2026-10-18').slice(0,10))}</summary><pre class="co-document">${esc(v.body)}</pre></details>`).join('')}</details>`);return true;}
  if(action==='co-edit-model'){const m=K.catalog(ops).find(m=>m.id===e.dataset.model);open('Nova versão do modelo',`<form id="co-model-form"><input type="hidden" name="modelId" value="${m.id}"><div class="notice">Texto demonstrativo. A nova versão preserva a anterior e só será usada nas próximas minutas. Não inserir qualificação ou documentos pessoais.</div><div class="gap">${input('description','Descrição do modelo',m.description,'required maxlength="300"')}</div><label class="field gap">Texto-base<textarea name="body" rows="15" maxlength="12000" required>${esc(m.body)}</textarea></label><p class="caption">Campos disponíveis: {{MOTORISTA}}, {{CARRO}}, {{PLACA}}, {{INICIO}}, {{FIM}}, {{ALUGUEL_SEMANAL}}, {{CAUCAO}}, {{LIMITE_KM}}, {{CONDICOES}}. Campos desconhecidos ficam pendentes na prévia.</p>${coFormActions('Salvar nova versão do modelo')}</form>`);return true;}
  if(action==='co-contract'){open('Meu advogado · documento e versões',coContractBody(id));return true;}
  if(action==='co-edit-contract'){open('Nova versão da minuta',coContractForm(K.contracts(ops).find(c=>c.id===id)));return true;}
  if(action==='co-review'){open('Conferir versão para assinatura',coReviewForm(id));return true;}
  if(action==='co-queue'){K.queueContract(ops,id);persist();render();open('Meu advogado · documento e versões',coContractBody(id));toast('Na fila demonstrativa. Nenhum documento foi enviado.');return true;}
  if(action==='co-await'){K.markAwaiting(ops,id);persist();render();open('Meu advogado · documento e versões',coContractBody(id));toast('Envio apenas simulado. Agora é possível registrar as partes no exemplo.');return true;}
  if(action==='co-sign'){open('Registro demonstrativo de signatário',`<form id="co-sign-form"><input type="hidden" name="entityId" value="${esc(id)}"><input type="hidden" name="party" value="${esc(e.dataset.party)}"><div class="notice amber">Isto não é assinatura eletrônica. Registra apenas uma conferência fictícia nesta demonstração.</div><p class="gap">Parte: <strong>${e.dataset.party==='driver'?'motorista':'locadora'}</strong>.</p>${input('date','Data do registro fictício',K.operatingDate,'type="date" required')}<label class="check gap"><input type="checkbox" name="confirm" required>Entendi que este registro é apenas demonstrativo</label>${coFormActions('Registrar parte no exemplo')}</form>`);return true;}
  if(action==='co-refuse'||action==='co-cancel'){open(action==='co-refuse'?'Recusa do documento':'Cancelar documento',`<form id="co-contract-reason-form"><input type="hidden" name="entityId" value="${esc(id)}"><input type="hidden" name="operation" value="${action==='co-refuse'?'refuse':'cancel'}"><label class="field">Motivo<textarea name="reason" maxlength="500" rows="3" required></textarea></label>${coFormActions('Registrar com motivo')}</form>`);return true;}
  if(action==='co-new-appointment'){open('Novo compromisso',coAppointmentForm());return true;}
  if(action==='co-agenda-view'){ops.agenda.view=e.dataset.view==='month'?'month':'week';render();persist();return true;}
  if(action==='co-agenda-today'){ops.agenda.anchor=K.operatingDate;render();persist();return true;}
  if(action==='co-agenda-shift'){const d=coDay(ops.agenda.anchor||K.operatingDate),dir=Number(e.dataset.dir);if(ops.agenda.view==='month'){d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+dir);}else d.setUTCDate(d.getUTCDate()+7*dir);ops.agenda.anchor=coIso(d);render();persist();return true;}
  if(action==='co-agenda-complete'){K.completeAppointment(ops,id);close();render();persist();toast('Compromisso manual concluído.');return true;}
  if(action==='co-edit-appointment'){open('Editar compromisso',coAppointmentForm(ops.agenda.events.find(e=>e.id===id)));return true;}
  if(action==='co-agenda-detail'){const item=K.agendaItems(ops).find(item=>item.id===id);if(!item)throw new RangeError('Compromisso não encontrado.');open('Agenda · detalhe',row(esc(item.title),date(item.date)+' · '+esc(item.time))+row('Responsável',esc(item.owner))+row('Vínculo',item.driverId?esc(coDriver(item.driverId)):'Sem motorista',item.vehicleId?esc(item.vehicleId):'')+`<p class="notice gap">${esc(item.note||'Sem observações.')}</p><div class="actions gap">`+(item.derived?btn('Conferir e resolver na origem','go-'+K.originFor(item),'primary'):btn('Editar compromisso','co-edit-appointment','',`data-id="${item.id}"`)+(item.status==='open'?btn('Concluir compromisso','co-agenda-complete','primary',`data-id="${item.id}"`):''))+'</div>'+(item.derived?'<p class="caption">Gerado do registro original. A agenda não confirma pagamentos nem documentos.</p>':''));return true;}
  return false;
 }
 function coordinationSubmit(form,f){if(form.id==='co-timezone-form'){K.setTimeZone(ops,String(f.get('timeZone')));close();render();persist();toast('Fuso da agenda atualizado.');return true;}if(!form.id.startsWith('co-'))return false;const id=String(f.get('entityId')||''),n=key=>Number(f.get(key));let contractId=null;
  if(form.id==='co-model-form'){K.saveModelVersion(ops,String(f.get('modelId')),{description:f.get('description'),body:f.get('body')});}
  else if(form.id==='co-contract-form'){const input={modelId:String(f.get('modelId')||''),driverId:String(f.get('driverId')),vehicleId:String(f.get('vehicleId')),startDate:String(f.get('startDate')),endDate:String(f.get('endDate')),weekly:n('weekly'),deposit:n('deposit'),kmLimit:n('kmLimit'),conditions:String(f.get('conditions')||'')};contractId=(id?K.updateContract(ops,id,input):K.createContract(ops,input)).id;}
  else if(form.id==='co-review-form'){K.reviewContract(ops,id,Object.fromEntries(K.reviewItems.map(([key])=>[key,f.has(key)])));contractId=id;}
  else if(form.id==='co-sign-form'){if(!f.has('confirm'))throw new RangeError('Confirme o caráter demonstrativo.');K.recordSignature(ops,id,String(f.get('party')),String(f.get('date')));contractId=id;}
  else if(form.id==='co-contract-reason-form'){if(f.get('operation')==='refuse')K.rejectContract(ops,id,String(f.get('reason')));else K.cancelContract(ops,id,String(f.get('reason')));contractId=id;}
  else if(form.id==='co-appointment-form'){const input={title:f.get('title'),owner:f.get('owner'),date:f.get('date'),time:f.get('time'),driverId:f.get('driverId'),vehicleId:f.get('vehicleId'),reminder:n('reminder'),status:f.get('status')||'open',note:f.get('note')};if(id)K.updateAppointment(ops,id,input);else K.addAppointment(ops,input);}
  else return false;
  persist();close();render();if(contractId)open('Meu advogado · documento e versões',coContractBody(contractId));toast(contractId?'Documento demonstrativo atualizado, com histórico.':form.id==='co-model-form'?'Nova versão do modelo salva. Documentos anteriores preservados.':'Compromisso salvo na agenda.');return true;
 }
